// Formatera den omfattande e-postrapporten
const designAnalysis = $('Agent 1: Designkritiker').item.json.output;
const copyAnalysis = $('Agent 2: Copywriter').item.json.output;
const seoAnalysis = $('Agent 3: SEO & Teknisk').item.json.output;
const strategyAnalysis = $('Agent 4: Tillväxtstrateg').item.json.output;

const userData = $('Initiera Variabler').item.json;
const pageData = $('Extrahera Sidelement').item.json;

// Extrahera betyg och poäng från strategianalysen
const gradeMatch = strategyAnalysis.match(/Betyg:\s*([A-F][+-]?)/i);
const grade = gradeMatch ? gradeMatch[1] : 'N/A';

const scoreMatch = strategyAnalysis.match(/Poäng:\s*(\d+)\/100/i);
const score = scoreMatch ? scoreMatch[1] : '0';

// Bestäm betygsfärg
const getGradeColor = (grade) => {
  if (grade.startsWith('A')) return '#28a745';
  if (grade.startsWith('B')) return '#17a2b8';
  if (grade.startsWith('C')) return '#ffc107';
  if (grade.startsWith('D')) return '#fd7e14';
  return '#dc3545';
};

const gradeColor = getGradeColor(grade);

// Formatera sektioner för e-post
const formatSection = (content, title, icon, color) => {
  return `
    <div style="margin: 30px 0; padding: 20px; background: #f8f9fa; border-left: 4px solid ${color}; border-radius: 4px;">
      <h2 style="margin: 0 0 15px 0; color: ${color}; font-size: 20px;">${icon} ${title}</h2>
      <div style="white-space: pre-line; line-height: 1.8; color: #333;">${content}</div>
    </div>
  `;
};

const emailHtml = `
